1	export const E2E_AUTH_BYPASS_COOKIE = 'hilo-e2e-auth-bypass';
2	export const E2E_AUTH_BYPASS_USER_COOKIE = 'hilo-e2e-auth-user';
3	export const DEFAULT_E2E_AUTH_BYPASS_SECRET = 'local-e2e-auth-bypass-secret';
4	
5	export type E2eAuthRole = 'user' | 'admin' | 'super_admin' | 'owner';
6	
7	export interface E2eAuthUser {
8	  id: string;
9	  email: string;
10	  name: string;
11	  role: E2eAuthRole;
12	  mustChangePassword?: boolean;
13	  flightSchoolId?: string;
14	  appUserId?: string;
15	  teamRole?: string;
16	  linkedStudentId?: string;
17	  assignedLocationIds?: string[];
18	  orgName?: string;
19	}
20	
21	function isProductionRuntime(): boolean {
22	  return process.env.NODE_ENV === 'production';
23	}
24	
25	export function isServerE2eAuthBypassEnabled(): boolean {
26	  return process.env.E2E_AUTH_BYPASS === 'true' && !isProductionRuntime();
27	}
28	
29	export function isClientE2eAuthBypassEnabled(): boolean {
30	  return (
31	    process.env.NEXT_PUBLIC_E2E_AUTH_BYPASS === 'true' && !isProductionRuntime()
32	  );
33	}
34	
35	export function getE2eAuthBypassSecret(): string {
36	  return process.env.E2E_AUTH_BYPASS_SECRET ?? DEFAULT_E2E_AUTH_BYPASS_SECRET;
37	}
38	
39	function parseCookieHeader(cookieHeader: string | null): Map<string, string> {
40	  const cookies = new Map<string, string>();
41	  if (!cookieHeader) return cookies;
42	
43	  for (const part of cookieHeader.split(';')) {
44	    const [rawName, ...rawValueParts] = part.trim().split('=');
45	    if (!rawName) continue;
46	    cookies.set(rawName, decodeURIComponent(rawValueParts.join('=')));
47	  }
48	
49	  return cookies;
50	}
51	
52	export function hasValidE2eAuthBypassCookie(headers: Headers): boolean {
53	  if (!isServerE2eAuthBypassEnabled()) return false;
54	  const cookies = parseCookieHeader(headers.get('cookie'));
55	  return cookies.get(E2E_AUTH_BYPASS_COOKIE) === getE2eAuthBypassSecret();
56	}
57	
58	export function getE2eAuthBypassUser(headers: Headers): E2eAuthUser | null {
59	  if (!hasValidE2eAuthBypassCookie(headers)) return null;
60	
61	  const cookies = parseCookieHeader(headers.get('cookie'));
62	  const rawUser = cookies.get(E2E_AUTH_BYPASS_USER_COOKIE);
63	  if (!rawUser) {
64	    return {
65	      id: 'e2e-super-admin',
66	      email: 'test.superadmin@hiloaviation.com',
67	      name: 'E2E Super Admin',
68	      role: 'super_admin',
69	      mustChangePassword: false,
70	    };
71	  }
72	
73	  try {
74	    const decoded = JSON.parse(rawUser) as Partial<E2eAuthUser>;
75	    if (!decoded.id || !decoded.email || !decoded.role) return null;
76	    return {
77	      id: decoded.id,
78	      email: decoded.email,
79	      name: decoded.name ?? decoded.email,
80	      role: decoded.role,
81	      mustChangePassword: Boolean(decoded.mustChangePassword),
82	      flightSchoolId: decoded.flightSchoolId,
83	      appUserId: decoded.appUserId,
84	      teamRole: decoded.teamRole,
85	      linkedStudentId: decoded.linkedStudentId,
86	      assignedLocationIds: decoded.assignedLocationIds,
87	      orgName: decoded.orgName,
88	    };
89	  } catch {
90	    return null;
91	  }
92	}
93	
94	export function readClientE2eAuthUser(): E2eAuthUser | null {
95	  if (!isClientE2eAuthBypassEnabled()) return null;
96	  if (typeof window === 'undefined') return null;
97	
98	  try {
99	    const raw = window.localStorage.getItem('hilo_e2e_auth_user');
100	    if (!raw) return null;
101	    const parsed = JSON.parse(raw) as Partial<E2eAuthUser>;
102	    if (!parsed.id || !parsed.email || !parsed.role) return null;
103	    return {
104	      id: parsed.id,
105	      email: parsed.email,
106	      name: parsed.name ?? parsed.email,
107	      role: parsed.role,
108	      mustChangePassword: Boolean(parsed.mustChangePassword),
109	      flightSchoolId: parsed.flightSchoolId,
110	      appUserId: parsed.appUserId,
111	      teamRole: parsed.teamRole,
112	      linkedStudentId: parsed.linkedStudentId,
113	      assignedLocationIds: parsed.assignedLocationIds,
114	      orgName: parsed.orgName,
115	    };
116	  } catch {
117	    return null;
118	  }
119	}
